import{z as p,x as A,o as i,c as n,q as t,j as e,D as E,d as B,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"PPO 的信任域重读","description":"","frontmatter":{"title":"PPO 的信任域重读","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ppo-clip-view.md","filePath":"llm/ppo-clip-view.md","lastUpdated":1791413859000}'),m={name:"llm/ppo-clip-view.md"};function s(c,a,h,_,P,d){const l=A("Mermaid");return i(),n("div",null,[a[2]||(a[2]=t('<h1 id="ppo-的信任域重读" tabindex="-1">PPO 的信任域重读 <a class="header-anchor" href="#ppo-的信任域重读" aria-label="Permalink to &quot;PPO 的信任域重读&quot;">​</a></h1><div class="epigraph"><p>PPO 把「别走太远」从二阶约束改成一条一阶裁剪：比率出带即停发梯度——信任域的承诺打了折，工程账却好算得多。</p><footer>—— 据 Schulman et al., Proximal Policy Optimization Algorithms, 2017 及其在 LLM 后训练的工程化整理</footer></div><p><a href="/llm/trust-region-monotone">上一课</a>把单调改进折成 KL 约束下的代理最大化，代价是共轭梯度、Fisher-向量积与线搜索。千亿参数、每步 rollout 以万 token 计的 LLM 场景里，这份二阶开销要求把信任域再做一次降维：只留一阶。本课用信任域语言重读 PPO 的 clip——裁剪比率是逐样本的近似信赖域——并与 <a href="/llm/reinforce-llm">REINFORCE / R3</a>、<a href="/llm/grpo">GRPO</a> 对位：GRPO 保留裁剪、去掉价值函数，是无 critic 的折中。PPO 在 LLM 里的实现细节见 <a href="/llm/ppo-llm">PPO</a> 一课，此处不重复。至此本单元把定理、方差、基线、自举、信任域走完；下一单元把长期后果整个拿掉，从上下文 bandit 这个最小案例重新审视后训练——那是收束单元的第一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TRPO 的一阶目标配上二阶度量，慢在两处：共轭梯度每步多几次反向传播，线搜索要反复评估代理目标。而 LLM 训练另有动机想「走得远一点」：一批昂贵的 rollout 想用好几个 epoch 的 minibatch 更新，\\(\\pi_\\theta\\) 相对采样策略 \\(\\pi_{\\mathrm{old}}\\) 的偏离随更新累积，重要性比率迅速失控——不设防的多轮复用等于在错误的分布上做梯度上升。需要一个机制：允许多次小更新，同时每个样本上的偏离有硬上限，且全程一阶。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记逐 token 比率 \\(r_t(\\theta)=\\pi_\\theta(a_t\\mid s_t)/\\pi_{\\mathrm{old}}(a_t\\mid s_t)\\)，PPO 的裁剪目标是</p><p><span class="marginnote">比率可以读成「新策略比旧策略更爱这个动作几倍」：\\(r_t=1\\) 表示没变，\\(r_t=1.5\\) 表示概率被抬高了 50%。多 epoch 复用同一批数据，本质就是监控这个倍数别离 1 太远。</span></p> \\[L^{\\mathrm{CLIP}}(\\theta)=\\mathbb{E}\\bigl[\\min\\bigl(r_t\\hat A_t,\\ \\mathrm{clip}(r_t,1-\\epsilon,1+\\epsilon)\\hat A_t\\bigr)\\bigr],\\quad \\epsilon\\approx 0.2. \\]<p>按 \\(\\hat A_t\\) 的符号读：\\(\\hat A_t\\gt 0\\) 且 \\(r_t\\gt 1+\\epsilon\\) 时，目标被钉在 \\((1+\\epsilon)\\hat A_t\\)，梯度归零——不再奖励继续抬高；\\(\\hat A_t\\lt 0\\) 且 \\(r_t\\lt 1-\\epsilon\\) 时同理。带内照常更新，带外停发。原论文另给 KL 惩罚变体，工程上常以「KL 到 \\(\\pi_{\\mathrm{old}}\\) 超标即早停」的形式保留一角。</p>',10)),(i(),e(o,null,{default:E(()=>[r(l,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%AF%94%E7%8E%87%20r%20%3D%20%CF%80%CE%B8%20%2F%20%CF%80old%22%5D%20--%3E%20S%7B%22%C3%82%20%E7%9A%84%E7%AC%A6%E5%8F%B7%E4%B8%8E%20r%20%E4%BD%8D%E7%BD%AE%22%7D%0A%20%20S%20--%3E%7C%22%E6%AD%A3%E4%BC%98%E5%8A%BF%EF%BC%8Cr%20%E8%B6%8A%E4%B8%8A%E7%95%8C%22%7C%20UP%5B%22%E7%9B%AE%E6%A0%87%E9%92%89%E5%B9%B3%EF%BC%9A%E6%A2%AF%E5%BA%A6%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20S%20--%3E%7C%22%E8%B4%9F%E4%BC%98%E5%8A%BF%EF%BC%8Cr%20%E7%A0%B4%E4%B8%8B%E7%95%8C%22%7C%20DOWN%5B%22%E7%9B%AE%E6%A0%87%E9%92%89%E5%B9%B3%EF%BC%9A%E6%A2%AF%E5%BA%A6%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20S%20--%3E%7C%22%E5%B8%A6%E5%86%85%22%7C%20MIN%5B%22%E5%8F%96%20min%20%E5%90%8E%E7%85%A7%E5%B8%B8%E5%8A%A0%E6%9D%83%E6%9B%B4%E6%96%B0%22%5D%0A%20%20UP%20--%3E%20SUM%5B%22%E6%B1%87%E6%80%BB%E5%81%9A%E4%B8%80%E9%98%B6%E6%9B%B4%E6%96%B0%22%5D%0A%20%20MIN%20--%3E%20SUM%0A%20%20DOWN%20--%3E%20SUM%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">裁剪没有拉回力：比率越界后目标对该样本的梯度恰为零，既不奖励继续越界，也不把它推回带内——推回的力来自别的样本或 KL 早停。诊断要看 clip fraction：长期大面积顶格，说明 \\(\\epsilon\\) 名存实亡，学习率该降了。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与上一课的硬约束对读：KL 球是全局的、二阶度量的，且带单调界；clip 是逐样本的、一阶的、乘性的，没有改进保证。它约束的是「单个样本的优势不被无限放大」，悲观化的 \\(\\min\\) 让裁剪只在「会进一步推高性能估计」的方向生效——反方向（把已采到的概率压回去）不受限，所以它是不对称的信赖域。这个保证更弱，换来的是：无需 Fisher、无需线搜索，一阶优化器直接跑，多 epoch 复用在比率带内近似安全。GRPO 的位置在此看得最清楚：保留 clip 与参考 KL（信任域那半），去掉 critic 与 GAE（自举那半），组基线补位——是在同一张蓝图上按 LLM 的显存与生成预算重划的取舍。<a href="/llm/reinforce-llm">REINFORCE / R3</a> 那条纯蒙特卡洛路线则连裁剪都不留，靠参考 KL 的拖曳防崩。</p><p><span class="marginnote">\\(\\min\\) 的直觉：在两个「这个样本值多少」的说法里挑悲观的那个。好处是不给「继续吹大优势」的方向发梯度——宁可不赚这笔，也不信夸大的账。</span></p><p>从二阶硬约束到一阶软约束的降档路径，每一步各留什么、扔什么：</p>',5)),(i(),e(o,null,{default:E(()=>[r(l,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20LR%0A%20%20TRPO%5B%22TRPO%EF%BC%9AKL%20%E7%90%83%E7%A1%AC%E7%BA%A6%E6%9D%9F%20%2B%20%E4%BA%8C%E9%98%B6%E5%BA%A6%E9%87%8F%22%5D%20--%3E%7C%22%E5%8F%AA%E7%95%99%E4%B8%80%E9%98%B6%22%7C%20PPO%5B%22PPO%EF%BC%9A%E9%80%90%E6%A0%B7%E6%9C%AC%20clip%20%E8%BD%AF%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20PPO%20--%3E%7C%22%E5%8E%BB%20critic%20%E4%B8%8E%20GAE%22%7C%20GRPO%5B%22GRPO%EF%BC%9Aclip%20%2B%20%E5%8F%82%E8%80%83%20KL%20%2B%20%E7%BB%84%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20PPO%20--%3E%7C%22%E8%BF%9E%20clip%20%E4%B9%9F%E4%B8%8D%E8%A6%81%22%7C%20R3%5B%22R3%EF%BC%9A%E7%BA%AF%E8%92%99%E7%89%B9%E5%8D%A1%E6%B4%9B%20%2B%20KL%20%E6%8B%96%E6%9B%B3%22%5D%0A%20%20TRPO%20--%3E%20G1%5B%22%E7%95%99%EF%BC%9A%E8%BF%91%E4%BC%BC%E5%8D%95%E8%B0%83%E6%94%B9%E8%BF%9B%EF%BC%9B%E4%BB%98%EF%BC%9A%E4%BA%8C%E9%98%B6%E5%BC%80%E9%94%80%22%5D%0A%20%20PPO%20--%3E%20G2%5B%22%E7%95%99%EF%BC%9A%E5%B8%A6%E5%86%85%E8%BF%91%E4%BC%BC%E5%AE%89%E5%85%A8%EF%BC%9B%E4%BB%98%EF%BC%9A%E5%8D%95%E8%B0%83%E7%95%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>信任域语言的三个警告。其一，clip 不惩罚越界只停发梯度：比率可以一路贴边走远，KL 早停是补丁不是定理。其二，\\(\\epsilon=0.2\\) 来自连续控制的实验默认，LLM 实现里它与 KL 目标、minibatch 数耦合，跨栈迁移要重调。其三，整套论证假设优势 \\(\\hat A_t\\) 是在 \\(\\pi_{\\mathrm{old}}\\) 下估的——GAE 的 critic 滞后、组基线的偏差都会让「带内」也不安全，裁剪不修优势估计的错。多 epoch 更新时监控三件：clip fraction、对 \\(\\pi_{\\mathrm{old}}\\) 的逐 minibatch KL、比率分布的漂移。把长期后果拿掉之后这套机制还剩多少，是下一单元上下文 bandit 要回答的问题。</p><p><span class="marginnote">为什么盯 clip fraction：若三成以上的样本长期顶格，说明学习率或 \\(\\epsilon\\) 已经失配——大部分样本不发梯度，等效批量在缩水，训练看着在跑，其实没学多少东西。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>clip = 逐样本的乘性信赖域：比率出带即停发梯度，全程一阶、无 Fisher、无线搜索。</li><li>\\(\\min\\) 的悲观化使裁剪不对称：只挡「进一步放大优势」，不挡回撤。</li><li>保证弱于 TRPO（无单调界），换来多 epoch 复用与 LLM 规模的可跑性。</li><li>GRPO = 保留裁剪与参考 KL、去掉 critic 的折中；R3 连裁剪也不留，靠 KL 拖曳。</li><li>监控 clip fraction 与逐 minibatch KL；优势估计的误差不被裁剪修复。</li><li>出处：Schulman et al., <em>Proximal Policy Optimization Algorithms</em>, 2017；Schulman et al., TRPO, 2015；Shao et al., DeepSeekMath, 2024。</li></ul>',5))])}const L=p(m,[["render",s]]);export{F as __pageData,L as default};
